package ps.lambda.patterns.factory.registry;import ps.lambda.patterns.factory.factory.Factory;import ps.lambda.patterns.factory.model.Rectangle;import ps.lambda.patterns.factory.model.Shape;import ps.lambda.patterns.factory.model.Square;import ps.lambda.patterns.factory.model.Triangle;public class SwitchRegistry {	public Factory<? extends Shape> buildShapeFactory(String shape) {				switch(shape) {			case "square" : return () -> new Square();			case "triangle" : return () -> new Triangle();			case "rectangle" : return () -> new Rectangle();			default:				throw new IllegalArgumentException("Unknown shape: " + shape);		}	}}